// ISBR meerkeuzevragen: drie opties zoals op de eindtoets. a = index juiste optie (de app schudt).
// Stellingenvragen: {st:true, s1, s2, a:'JJ'|'JO'|'OJ'|'OO'}
window.MC = [
// ---------- WEEK 1 ----------
{w:1,k:"rechtsstaat",t:"Beginselen",q:"Een gemeente wil inwoners die hun stoep niet vegen een boete van €100 opleggen. Er bestaat geen wettelijke regeling die de gemeente die bevoegdheid geeft. Welk beginsel van de democratische rechtsstaat staat hier vooral in de weg?",o:["Het legaliteitsbeginsel","Het democratiebeginsel","De onafhankelijkheid van de rechter"],a:0,e:"Voor optreden dat burgers bindt of hun vrijheid beperkt, zoals een boete, is in beginsel een wettelijke bevoegdheid nodig. Een bestuursorgaan mag geen bevoegdheden verzinnen."},
{w:1,k:"rechtsstaat",t:"Beginselen",q:"Een minister belt een rechter en vraagt hem in een lopende zaak ‘rekening te houden met het belang van het kabinet’. Wat wordt hier vooral geraakt?",o:["De onafhankelijkheid van de rechter","Het democratiebeginsel","Het specialiteitsbeginsel"],a:0,e:"Onafhankelijk betekent dat de rechter geen opdrachten krijgt over de uitkomst, bijvoorbeeld van een minister. Onpartijdigheid gaat over het niet kiezen van partij voor een van de betrokkenen."},
{w:1,k:"publiek",t:"Publiek of privaat",q:"De gemeente Zeist koopt nieuwe bureaus voor het gemeentehuis bij een meubelzaak. Welk recht is op deze koop van toepassing?",o:["Het privaatrecht","Het bestuursrecht","Het staatsrecht"],a:0,e:"De overheid kan ook privaatrechtelijk handelen. Een koopovereenkomst sluiten is een privaatrechtelijke rechtshandeling, ook als de gemeente koper is."},
{w:1,k:"publiek",t:"Functies",q:"Welke functie van het bestuursrecht staat centraal als een burger met succes opkomt tegen een onrechtmatig besluit?",o:["De waarborgfunctie","De instrumentele functie","De normerende functie"],a:0,e:"Waarborgfunctie: bescherming van burgers tegen onrechtmatig overheidsoptreden (bestuursrecht ‘tegen’ het bestuur). Instrumenteel: middelen ‘van’ het bestuur. Normerend: regels ‘voor’ het bestuur."},
{w:1,k:"publiek",t:"Functies",q:"Een bepaling in de Gemeentewet stelt de functie van wethouder in. Welke functie van het staatsrecht zie je hier vooral?",o:["Constitueren","Attribueren","Legitimeren"],a:0,e:"Constitueren is het instellen van ambten en organen. Attribueren is het toekennen van bevoegdheden aan die ambten."},
{w:1,k:"kernbegrippen",t:"Handelingen",q:"De gemeente laat bomen in een park snoeien. Wat voor handeling is dit?",o:["Een feitelijke handeling","Een publiekrechtelijke rechtshandeling","Een privaatrechtelijke rechtshandeling"],a:0,e:"Een feitelijke handeling is niet gericht op het laten ontstaan van een rechtsgevolg. Snoeien verandert geen rechten of plichten."},
{w:1,k:"kernbegrippen",t:"Ambt",q:"Burgemeester Jansen gaat met pensioen en wordt opgevolgd door burgemeester De Vries. Wat blijft bestaan?",o:["Het ambt van burgemeester","De ambtsdrager","De bevoegdheden van Jansen persoonlijk"],a:0,e:"Het ambt is een blijvende overheidsfunctie met taken en bevoegdheden. De ambtsdrager is de persoon die het ambt vervult en kan wisselen."},
{w:1,k:"bronnen",t:"Bronnen",st:true,q:"Lees de volgende stellingen.",s1:"De staatsrechtelijke vertrouwensregel is een voorbeeld van ongeschreven recht.",s2:"Een annotatie bij een uitspraak is net zo bindend als wetgeving.",a:"JO",e:"De vertrouwensregel is gewoonterecht, dus ongeschreven. Annotaties en literatuur zijn kenbronnen en hulpmiddelen bij uitleg; ze binden niet zoals wetgeving."},
{w:1,k:"rechtsstaat",t:"Grondwet",q:"Welke uitspraak over de algemene bepaling van de Grondwet (‘De Grondwet waarborgt de grondrechten en de democratische rechtsstaat’) is juist?",o:["Zij is in 2022 aan de Grondwet toegevoegd","Zij stamt uit de herziening van 1848","Zij is in 2014 aan de Grondwet toegevoegd"],a:0,e:"De algemene bepaling is in 2022 toegevoegd. Let op: in je oorspronkelijke aantekeningen stond 2014."},
{w:1,k:"abbb",t:"Abbb",q:"Welk beginsel van behoorlijk bestuur staat in art. 3:3 Awb?",o:["Het verbod van détournement de pouvoir","Het evenredigheidsbeginsel","Het zorgvuldigheidsbeginsel"],a:0,e:"Art. 3:3 Awb: een bevoegdheid mag niet voor een ander doel worden gebruikt dan waarvoor zij is verleend. Zorgvuldigheid staat in art. 3:2, evenredigheid in art. 3:4 lid 2."},
{w:1,k:"kernbegrippen",t:"Belanghebbende",q:"Wie is volgens art. 1:2 Awb belanghebbende?",o:["Degene wiens belang rechtstreeks bij een besluit is betrokken","Iedereen die zich door een besluit geraakt voelt","Iedere inwoner van de gemeente die het besluit nam"],a:0,e:"Het belang moet rechtstreeks bij het besluit betrokken zijn. Alleen ‘geraakt worden’ is niet altijd genoeg."},

// ---------- WEEK 2 ----------
{w:2,k:"organen",t:"Organen",q:"Uit wie bestaat de regering?",o:["De Koning en de ministers","De ministers en de staatssecretarissen","De Koning, de ministers en de staatssecretarissen"],a:0,e:"Regering = Koning + ministers. Kabinet = ministers + staatssecretarissen."},
{w:2,k:"organen",t:"Kamers",st:true,q:"Lees de volgende stellingen over de Kamers.",s1:"De Eerste Kamer kan een wetsvoorstel wijzigen door een amendement aan te nemen.",s2:"De Eerste Kamer wordt rechtstreeks door de kiezers gekozen.",a:"OO",e:"Alleen de Tweede Kamer heeft het recht van amendement en initiatief. De Eerste Kamer wordt getrapt gekozen: door Provinciale Staten en kiescolleges."},
{w:2,k:"organen",t:"Kamerleden",q:"Een Kamerlid stapt uit zijn fractie, maar blijft in de Kamer zitten als eenmansfractie. Zijn oude partij eist dat hij zijn zetel opgeeft. Wat is juist?",o:["Hij hoeft zijn zetel niet af te staan, want Kamerleden stemmen zonder last (art. 67 lid 3 Gw)","Hij moet zijn zetel afstaan, want de zetel is van de partij","Hij moet zijn zetel afstaan als de meerderheid van de Kamer dat wil"],a:0,e:"Vrij mandaat: Kamerleden zijn juridisch niet gebonden aan stemopdrachten van partij of kiezers. Wie de fractie verlaat, hoeft zijn zetel niet af te staan."},
{w:2,k:"organen",t:"Kamerleden",q:"Een Kamerlid doet tijdens een debat in de Kamer een zeer scherpe uitspraak over een bedrijf. Het bedrijf wil hem aanklagen wegens smaad. Wat is juist?",o:["Dat kan niet: art. 71 Gw beschermt wat hij in de vergadering zegt","Dat kan, want Kamerleden staan niet boven de wet","Dat kan alleen als de Eerste Kamer toestemming geeft"],a:0,e:"Parlementaire onschendbaarheid (art. 71 Gw): deelnemers aan de beraadslagingen kunnen niet gerechtelijk worden vervolgd of aangesproken voor wat zij daar zeggen."},
{w:2,k:"democratie",t:"Democratie",q:"Welke van de volgende eisen is een materiële minimumeis van democratie?",o:["Toegang tot onafhankelijke informatie en een vrije pers","Vrije en geheime verkiezingen","Gelijk stemgewicht"],a:0,e:"Procedurele eisen gaan over hoe besluiten worden genomen (verkiezingen, stemgewicht, meerderheid). Materiële eisen maken echte invloed mogelijk, zoals vrije informatie, transparantie en vrij debat."},
{w:2,k:"democratie",t:"Democratie",q:"Wat betekent passief kiesrecht?",o:["Het recht om gekozen te worden","Het recht om te stemmen","Het recht om benoemd te worden in openbare dienst"],a:0,e:"Actief kiesrecht: stemmen. Passief kiesrecht: gekozen worden. Gelijke benoembaarheid in openbare dienst is een apart recht."},
{w:2,k:"democratie",t:"Kiesstelsel",q:"In een land wint per district de kandidaat met de meeste stemmen, ook als dat minder dan de helft is. Welk stelsel is dit?",o:["Een relatief meerderheidsstelsel","Evenredige vertegenwoordiging","Censuskiesrecht"],a:0,e:"Bij een relatief meerderheidsstelsel volstaat de meeste stemmen; stemmen op verliezers leveren geen zetel op. Nederland kent evenredige vertegenwoordiging."},
{w:2,k:"democratie",t:"Kiesstelsel",q:"Hoe wordt de kiesdeler voor de Tweede Kamer berekend?",o:["Het totaal aantal geldige stemmen gedeeld door 150","Het totaal aantal kiesgerechtigden gedeeld door 150","Het totaal aantal geldige stemmen gedeeld door het aantal partijen"],a:0,e:"Kiesdeler = geldige stemmen / 150. Elke lijst krijgt een zetel per volle kiesdeler; restzetels gaan via het systeem van de grootste gemiddelden."},
{w:2,k:"trias",t:"Trias politica",q:"Welke uitspraak over de trias politica in Nederland is juist?",o:["Organen hebben deels overlappende functies, werken samen en controleren elkaar","Wetgeving, bestuur en rechtspraak liggen bij strikt gescheiden organen","De regering heeft geen rol bij de wetgeving"],a:0,e:"Nederland kent geen strikte scheiding: regering en Staten-Generaal maken samen wetten (art. 81 Gw) en de machten controleren elkaar via checks and balances."},
{w:2,k:"trias",t:"Trias politica",q:"Welke van deze is een voorbeeld van checks and balances?",o:["De regering kan een Kamer ontbinden (art. 64 Gw)","De Koning is onschendbaar (art. 42 lid 2 Gw)","Kamerleden stemmen zonder last (art. 67 lid 3 Gw)"],a:0,e:"Het ontbindingsrecht is een middel van de regering tegenover het parlement, terwijl het parlement de regering controleert. Zo houden de machten elkaar in evenwicht."},
{w:2,k:"parlstelsel",t:"Geschiedenis",q:"Wat werd in 1840 ingevoerd?",o:["Strafrechtelijke ministeriële verantwoordelijkheid en het contraseign","Politieke ministeriële verantwoordelijkheid","Algemeen mannenkiesrecht"],a:0,e:"1840: strafrechtelijke verantwoordelijkheid en medeondertekening. 1848: politieke verantwoordelijkheid. 1917: algemeen mannenkiesrecht."},
{w:2,k:"parlstelsel",t:"Vertrouwensregel",q:"Welke uitspraak over de vertrouwensregel is juist?",o:["Het is ongeschreven staatsrecht dat zich na 1848 geleidelijk heeft ontwikkeld","Het staat in art. 42 lid 2 Gw","Het is in 1848 in de Grondwet opgenomen"],a:0,e:"De vertrouwensregel is gewoonterecht. Hij ontwikkelde zich na 1848, met de conflicten van 1866 tot 1868 als belangrijk moment. Art. 42 lid 2 Gw gaat over onschendbaarheid van de Koning en ministeriële verantwoordelijkheid."},
{w:2,k:"parlstelsel",t:"Verantwoordelijkheid",q:"Een minister voert beleid uit dat volledig binnen de wet blijft, maar de Kamer vindt het onverstandig. Kan de Kamer de minister daarop aanspreken?",o:["Ja, de Kamer beoordeelt ook de opportuniteit van het handelen","Nee, de Kamer mag alleen de rechtmatigheid beoordelen","Nee, alleen de rechter kan beleid beoordelen"],a:0,e:"Politieke ministeriële verantwoordelijkheid gaat over legaliteit én opportuniteit: was het verstandig en wenselijk?"},
{w:2,k:"parlstelsel",t:"Verantwoordelijkheid",q:"Welke stelling over de ministeriële verantwoordelijkheid is juist?",o:["Ministers zijn verantwoordelijk voor het optreden van de Koning","Ministers zijn verantwoordelijk voor wat hun fractiegenoten in de Kamer zeggen","Staatssecretarissen nemen de verantwoordelijkheid van de minister volledig over"],a:0,e:"Art. 42 lid 2 Gw: de Koning is onschendbaar, de ministers zijn verantwoordelijk. Fractieleden vallen niet onder ministeriële verantwoordelijkheid. Bij staatssecretarissen blijft de verantwoordelijkheid van de minister bestaan."},
{w:2,k:"parlbevoegd",t:"Moties",q:"De Tweede Kamer neemt een motie van treurnis aan tegen een minister. Wat is het juridische gevolg?",o:["Geen juridische plicht tot aftreden; de motie spreekt alleen betreuren uit","De minister moet op grond van de vertrouwensregel ontslag aanbieden","De minister moet op grond van art. 68 Gw de Kamer volledig informeren"],a:0,e:"Een gewone motie is juridisch niet bindend. Alleen bij vastgesteld verlies van vertrouwen, zoals een aangenomen motie van wantrouwen, volgt uit de vertrouwensregel de plicht om ontslag aan te bieden."},
{w:2,k:"parlbevoegd",t:"Moties",q:"Waaruit volgt de plicht van een minister om ontslag aan te bieden na een aangenomen motie van wantrouwen?",o:["Uit de ongeschreven vertrouwensregel","Uit de motie zelf, die juridisch bindend is","Uit art. 68 Gw"],a:0,e:"Moties zijn juridisch niet bindend. De ontslagplicht vloeit voort uit de vertrouwensregel, ongeschreven staatsrecht."},
{w:2,k:"parlbevoegd",t:"Bevoegdheden parlement",q:"Een Kamerlid wil van de minister alle interne rapporten over een mislukt ICT-project ontvangen. Op welke bevoegdheid beroept hij zich?",o:["Het inlichtingenrecht (art. 68 Gw)","Het enquêterecht (art. 70 Gw)","Het budgetrecht (art. 105 Gw)"],a:0,e:"Het inlichtingenrecht geeft Kamerleden het recht informatie te vragen; de minister moet die geven tenzij het belang van de staat zich ertegen verzet."},
{w:2,k:"parlbevoegd",t:"Bevoegdheden parlement",q:"De Tweede Kamer wil getuigen onder ede horen over misstanden bij een uitvoeringsorganisatie. Welke bevoegdheid gebruikt zij?",o:["Het enquêterecht (art. 70 Gw)","Het inlichtingenrecht (art. 68 Gw)","Het recht van interpellatie"],a:0,e:"Een enquêtecommissie kan onder wettelijke voorwaarden getuigen en deskundigen horen, getuigen onder ede horen en documenten vorderen."},
{w:2,k:"parlbevoegd",t:"Bevoegdheden parlement",q:"Welke bevoegdheid heeft alleen de Tweede Kamer?",o:["Het recht van amendement","Het enquêterecht","Het inlichtingenrecht"],a:0,e:"Amendement en initiatief zijn voorbehouden aan de Tweede Kamer. Enquête- en inlichtingenrecht hebben beide Kamers."},
{w:2,k:"formatie",t:"Formatie",q:"Wie stelt tijdens een kabinetsformatie het kabinet samen en wordt vaak de nieuwe minister-president?",o:["De formateur","De informateur","De verkenner"],a:0,e:"Verkenner: mogelijkheden in kaart. Informateur: onderzoekt of partijen afspraken kunnen maken. Formateur: stelt het kabinet samen."},
{w:2,k:"formatie",t:"Formatie",q:"Wat is een demissionair kabinet?",o:["Een kabinet dat ontslag heeft aangeboden en voorlopig werkzaamheden blijft verrichten","Een kabinet zonder vaste parlementaire meerderheid","Een kabinet dat niet afhankelijk is van de vertrouwensregel"],a:0,e:"Demissionair: ontslag aangeboden, maar het blijft de lopende zaken behandelen. Een kabinet zonder vaste binding met een meerderheid heet extraparlementair; ook dat is afhankelijk van de vertrouwensregel."},

// ---------- WEEK 3 ----------
{w:3,k:"legaliteit",t:"Legaliteit",q:"Een gemeente voegt zonder wettelijke grondslag fluor toe aan het drinkwater om tandbederf te voorkomen. Welk arrest is hier het meest relevant?",o:["Fluoridering","Meerenberg","Methadonbrief"],a:0,e:"Fluoridering: ook een ingrijpende feitelijke maatregel kan een specifieke wettelijke grondslag vereisen."},
{w:3,k:"legaliteit",t:"Legaliteit",q:"Een minister stuurt artsen een brief met bindende voorschriften over het voorschrijven van een medicijn. Op overtreding staat geen straf. Is een wettelijke grondslag nodig?",o:["Ja, ook bindende voorschriften zonder strafrechtelijke handhaving kunnen een grondslag vereisen (Methadonbrief)","Nee, zonder strafbaarstelling is geen grondslag nodig","Nee, een minister mag altijd beleidsregels stellen"],a:0,e:"Methadonbrief: ook bindende overheidsvoorschriften zonder strafrechtelijke handhaving kunnen een wettelijke grondslag vereisen."},
{w:3,k:"legaliteit",t:"Legaliteit",q:"Welk arrest leert dat de regering niet uit zichzelf iedere bindende regel kan vaststellen, maar daarvoor een juridische bevoegdheid nodig heeft?",o:["Meerenberg","Rogge","Fluoridering"],a:0,e:"Meerenberg: de regering heeft voor bindende regels een bevoegdheid nodig. Rogge gaat over de kenmerken van een wet in materiële zin."},
{w:3,k:"legaliteit",t:"Legaliteit",q:"Welke functie van het legaliteitsbeginsel staat voorop als je zegt: ‘Burgers hebben via hun vertegenwoordigers invloed op de wettelijke grondslag van overheidsoptreden’?",o:["Democratische legitimatie","Rechtsgelijkheid","Willekeur voorkomen"],a:0,e:"De vier functies: willekeur voorkomen, rechtszekerheid, rechtsgelijkheid en democratische legitimatie. Deze zin beschrijft de democratische legitimatie."},
{w:3,k:"legaliteit",t:"Terugtred",q:"Beoordeel de stelling: ‘De terugtred van de formele wetgever staat op gespannen voet met het legaliteitsbeginsel.’",o:["Juist, want gedelegeerde regelgeving biedt doorgaans minder waarborgen voor democratische controle, legitimiteit en rechtszekerheid","Onjuist, want het legaliteitsbeginsel gaat alleen over feitelijk handelen","Onjuist, want lagere regelgeving is nooit een algemeen verbindend voorschrift"],a:0,e:"Bij terugtred verschuift normstelling naar het bestuur. Het parlement beslist dan niet mee over iedere uitgewerkte regel. Dat raakt de democratische legitimatie, een functie van het legaliteitsbeginsel."},
{w:3,k:"bevoegdheden",t:"Bevoegdheden",q:"Het college beslist op de aanvraag van mevrouw Bos om een standplaatsvergunning voor haar viskraam. Welke bevoegdheid gebruikt het college?",o:["Een bestuurs- of beschikkingsbevoegdheid","Een regelgevende bevoegdheid","Een wetgevende bevoegdheid"],a:0,e:"Het toepassen van regels in een concreet geval is een bestuursbevoegdheid. Regelgeving bepaalt wat in algemene gevallen geldt."},
{w:3,k:"bevoegdheden",t:"Bevoegdheden",q:"Een wet bepaalt: ‘Onze Minister kan een subsidie verlenen voor projecten die bijdragen aan duurzame energie.’ Waar wijst het woord ‘kan’ meestal op?",o:["Beleidsruimte","Beoordelingsruimte","Een gebonden bevoegdheid"],a:0,e:"‘Kan’ of ‘mag’ wijst vaak op beleidsruimte: ruimte om te beslissen óf en hoe de bevoegdheid wordt gebruikt. Eén woord is wel niet altijd beslissend."},
{w:3,k:"bevoegdheden",t:"Attributie",q:"Art. 127 Gw bepaalt dat Provinciale Staten en de gemeenteraad verordeningen vaststellen. Wat gebeurt hier?",o:["Attributie: een nieuwe bevoegdheid wordt gecreëerd en toegekend","Delegatie: een bestaande bevoegdheid wordt overgedragen","Subdelegatie: een gedelegeerde bevoegdheid wordt doorgegeven"],a:0,e:"Attributie is het creëren en toekennen van een nieuwe bevoegdheid. Er werd niets overgedragen."},
{w:3,k:"bevoegdheden",t:"Delegatie",q:"Op grond van welke grondwetsbepaling is delegatie van de beperkingsbevoegdheid door de formele wetgever toegestaan?",o:["Art. 10 lid 1 Gw: ‘behoudens bij of krachtens de wet te stellen beperkingen’","Art. 6 lid 1 Gw: ‘behoudens ieders verantwoordelijkheid volgens de wet’","Een bepaling met de formulering ‘bij de wet’"],a:0,e:"‘Bij of krachtens de wet’ staat delegatie toe. ‘Bij de wet’ en ‘behoudens ieders verantwoordelijkheid volgens de wet’ betekenen dat de formele wetgever het zelf moet regelen."},
{w:3,k:"bevoegdheden",t:"Delegatie",q:"Een AMvB draagt een regelgevende bevoegdheid verder over aan de minister. Hoe heet dat, en wat is daarvoor nodig?",o:["Subdelegatie; de bevoegdheidsgrondslag moet daar ruimte voor bieden","Attributie; de Grondwet moet het uitdrukkelijk noemen","Horizontale delegatie; het parlement moet vooraf instemmen"],a:0,e:"Subdelegatie: een gedelegeerde bevoegdheid wordt verder overgedragen. De grondslag moet daar ruimte voor laten."},
{w:3,k:"bevoegdheden",t:"Delegatie",q:"De formele wetgever draagt een regelgevende bevoegdheid over aan de gemeenteraad. Welke vorm van delegatie is dit?",o:["Verticale delegatie","Horizontale delegatie","Subdelegatie"],a:0,e:"Verticaal: tussen verschillende overheidsverbanden (Rijk naar gemeente). Horizontaal: binnen hetzelfde verband."},
{w:3,k:"bevoegdheden",t:"Delegatie",q:"Een wet bepaalt dat de voordracht voor een AMvB pas wordt gedaan nadat het ontwerp aan beide Kamers is voorgelegd. Welke vorm van parlementaire betrokkenheid is dit?",o:["Gecontroleerde delegatie","Tijdelijke delegatie","Voorwaardelijke delegatie"],a:0,e:"Bij gecontroleerde delegatie krijgt het parlement de ontwerpregeling voorgelegd. Tijdelijk: later vervangen door een formele wet. Voorwaardelijk: het parlement kan verlangen dat het alsnog bij wet wordt geregeld."},
{w:3,k:"regelgeving",t:"Regelgeving",q:"Welke regeling wordt vastgesteld bij koninklijk besluit, na behandeling in de ministerraad en advies van de Afdeling advisering van de Raad van State?",o:["Een algemene maatregel van bestuur","Een ministeriële regeling","Een wet in formele zin"],a:0,e:"Een AMvB wordt door de regering bij KB vastgesteld na ministerraad en advies van de Raad van State. Een formele wet wordt door regering en Staten-Generaal samen vastgesteld."},
{w:3,k:"regelgeving",t:"Regelgeving",st:true,q:"Lees de volgende stellingen.",s1:"Iedere regeling die bij koninklijk besluit wordt vastgesteld, is een algemene maatregel van bestuur.",s2:"Ministeriële regelingen worden doorgaans bekendgemaakt in de Staatscourant.",a:"OJ",e:"Niet ieder koninklijk besluit is een AMvB: een KB kan ook een individueel besluit zijn (bijv. een benoeming). Wetten en AMvB's staan in het Staatsblad, ministeriële regelingen doorgaans in de Staatscourant."},
{w:3,k:"regelgeving",t:"Regelgeving",st:true,q:"Lees de volgende stellingen.",s1:"Algemeen verbindende voorschriften kunnen alleen worden vastgesteld via wetten in formele zin, AMvB's en ministeriële regelingen.",s2:"Beleidsregels zijn algemeen verbindende voorschriften.",a:"OO",e:"Ook provinciale en gemeentelijke verordeningen zijn AVV's. En beleidsregels zijn geen AVV: ze gaan over hoe een orgaan een bevoegdheid gebruikt. Deze vraag kwam vrijwel zo op de eindtoets van 2025."},
{w:3,k:"regelgeving",t:"Regelgeving",q:"Een gemeentelijke verordening verbiedt alle inwoners om tussen 23.00 en 07.00 uur vuurwerk af te steken. Is dit een wet in materiële zin?",o:["Ja, het is een algemeen verbindend voorschrift van een orgaan met regelgevende bevoegdheid","Nee, alleen regels van regering en Staten-Generaal zijn wetten in materiële zin","Nee, want het is geen wet in formele zin"],a:0,e:"Wet in materiële zin = AVV: algemene kring, abstract en herhaalbaar, externe werking, bevoegd orgaan. De maker hoeft niet de formele wetgever te zijn."},
{w:3,k:"regelgeving",t:"Regelgeving",q:"Wat is gelede normstelling?",o:["De regels over één onderwerp staan verspreid over regelingen op verschillende niveaus, met een ononderbroken keten van attributie en delegatie","Een formele wet wordt in delen (tranches) ingevoerd","Een lagere regeling gaat voor op een hogere als zij specifieker is"],a:0,e:"Bijvoorbeeld: formele wet → AMvB → ministeriële regeling. Je moet dan meerdere regelingen lezen om te weten wat geldt. ‘In tranches’ is een kenmerk van de Awb als aanbouwwet."},
{w:3,k:"wetgeving",t:"Wetgeving",q:"Wat is de juiste volgorde?",o:["Bekrachtiging, bekendmaking, inwerkingtreding","Bekendmaking, bekrachtiging, inwerkingtreding","Inwerkingtreding, bekrachtiging, bekendmaking"],a:0,e:"Na aanvaarding door beide Kamers wordt het voorstel door bekrachtiging een wet. Daarna volgt bekendmaking in het Staatsblad. Een wet treedt nooit in werking vóór de bekendmaking."},
{w:3,k:"wetgeving",t:"Wetgeving",q:"Welke uitspraak over het advies van de Raad van State bij een wetsvoorstel is juist?",o:["Het advies is niet bindend; de regering reageert in een nader rapport","De regering moet het advies volledig overnemen","De Raad van State kan het wetsvoorstel zelf wijzigen"],a:0,e:"De Afdeling advisering adviseert; het advies bindt niet. De regering reageert in een nader rapport."},
{w:3,k:"bestuurskunde",t:"Legitimiteit",q:"Een gemeente krijgt lof omdat haar nieuwe aanpak van schulden aantoonbaar werkt: veel minder huisuitzettingen. Op welke vorm van legitimiteit wijst dit?",o:["Outputlegitimiteit","Inputlegitimiteit","Throughputlegitimiteit"],a:0,e:"Output: kwaliteit en resultaten. Input: democratische betrokkenheid. Throughput: een zorgvuldig en transparant proces."},
{w:3,k:"bestuurskunde",t:"Bestuurskunde",q:"Welke manier van denken over het bestuur legt de nadruk op efficiëntie, prestaties en kostenbeheersing?",o:["New Public Management","Public Value Management","Public Governance"],a:0,e:"NPM: efficiëntie en prestaties. Public Value Management: publieke waarde en de dienende overheid. Public Governance: samenwerking met private en maatschappelijke partijen."},

// ---------- WEEK 5 ----------
{w:5,k:"bestuursorgaan",t:"Bestuursorgaan",q:"Is de regering een bestuursorgaan in de zin van de Awb?",o:["Ja, omdat de regering een orgaan is van een publiekrechtelijke rechtspersoon (de Staat)","Nee, omdat de regering geen rechtspersoonlijkheid bezit","Nee, omdat de regering in de Awb is uitgezonderd van het bestuursorgaanbegrip"],a:0,e:"Voor een a-orgaan moet de rechtspersoon (de Staat) rechtspersoonlijkheid hebben, niet het orgaan zelf. De regering is een orgaan van de Staat. Deze vraag kwam zo op de eindtoets van 2025."},
{w:5,k:"bestuursorgaan",t:"Bestuursorgaan",q:"In welk geval is sprake van een bestuursorgaan in de zin van art. 1:1 Awb?",o:["De burgemeester van Utrecht die een lintje uitreikt op een buurtfeest","De rechtbank Midden-Nederland die uitspraak doet op een beroep tegen een vergunning","Het Hoogheemraadschap De Stichtse Rijnlanden (het waterschap zelf) dat nieuwe gemalen bestelt"],a:0,e:"De burgemeester is een orgaan van de gemeente en dus altijd a-orgaan, ook bij feitelijk handelen. De rechtbank is uitgezonderd (art. 1:1 lid 2 Awb). Het waterschap zelf is een rechtspersoon, geen orgaan."},
{w:5,k:"bestuursorgaan",t:"Bestuursorgaan",q:"Wat is juist over de gemeente Amersfoort en het college van B&W van Amersfoort?",o:["De gemeente is de rechtspersoon, het college is het bestuursorgaan","De gemeente is het bestuursorgaan, het college is de rechtspersoon","Beide zijn zowel rechtspersoon als bestuursorgaan"],a:0,e:"Publiekrechtelijke rechtspersonen (art. 2:1 BW) zijn de Staat, provincies, gemeenten en waterschappen. Hun organen zijn de a-bestuursorganen."},
{w:5,k:"bestuursorgaan",t:"Bestuursorgaan",q:"Een a-bestuursorgaan sluit een huurovereenkomst voor een kantoorpand. Is het daarbij een bestuursorgaan?",o:["Ja, een a-orgaan blijft bestuursorgaan, ook bij privaatrechtelijk handelen","Nee, alleen bij publiekrechtelijk handelen is het een bestuursorgaan","Alleen als de huurprijs met overheidsgeld wordt betaald"],a:0,e:"Bij a-organen staat de organisatorische positie centraal: het blijft bestuursorgaan bij publiekrechtelijk, privaatrechtelijk en feitelijk handelen. Wel gelden niet alle Awb-regels voor iedere handeling."},
{w:5,k:"bestuursorgaan",t:"Bestuursorgaan",q:"Een erkende APK-keurder, een privaat garagebedrijf, keurt een auto af. Wat is de keurder bij die beslissing?",o:["Een b-bestuursorgaan, want hij oefent wettelijk openbaar gezag uit","Een a-bestuursorgaan, want hij voert een publieke taak uit","Geen bestuursorgaan, want hij is een privaat bedrijf"],a:0,e:"Een privaat bedrijf kan b-orgaan zijn als het (wettelijk) openbaar gezag uitoefent: eenzijdig de rechtspositie van anderen bepalen. Dat is alleen zo voor zover het die bevoegdheid uitoefent."},
{w:5,k:"bestuursorgaan",t:"Bestuursorgaan",q:"Een stichting verdeelt sportsubsidies aan verenigingen. De gemeente betaalt 80% van het subsidiebudget, maar het stichtingsbestuur bepaalt zelf alle criteria. Is het bestuur van de stichting een b-orgaan?",o:["Nee, want het inhoudelijke vereiste is niet vervuld: a-organen bepalen de criteria niet in beslissende mate","Ja, want de verstrekking wordt in overwegende mate door een a-orgaan gefinancierd","Ja, want de stichting voert een publieke taak uit"],a:0,e:"Voor buitenwettelijk openbaar gezag moeten beide cumulatieve vereisten zijn vervuld: het inhoudelijke (a-organen bepalen de criteria) én het financiële (twee derde of meer). Alleen geld of een publieke taak is onvoldoende."},
{w:5,k:"bestuursorgaan",t:"Bestuursorgaan",q:"Wanneer kan een orgaan van een privaatrechtelijke rechtspersoon zonder wettelijke bevoegdheid toch b-orgaan zijn?",o:["Bij geldelijke uitkeringen of op geld waardeerbare voorzieningen, als a-organen de criteria bepalen én de verstrekkingen in overwegende mate financieren","Als het een publieke taak uitvoert in opdracht van de overheid","Als de overheid meer dan de helft van de organisatie financiert"],a:0,e:"Buitenwettelijk openbaar gezag: alleen voor uitkeringen en voorzieningen, met twee cumulatieve vereisten. Het gaat om de financiering van de verstrekkingen, niet om de algemene financiering van de organisatie."},
{w:5,k:"decentralisatie",t:"Decentralisatie",q:"Welke van onderstaande is een voorbeeld van functionele decentralisatie?",o:["De Nederlandse Orde van Advocaten","De provincie Utrecht","Het openbaar lichaam Bonaire"],a:0,e:"Functionele decentralisatie is gericht op bepaalde taken of beroepen, zoals een beroepsorganisatie. Provincies en de openbare lichamen (Bonaire, Sint Eustatius, Saba) zijn territoriaal."},
{w:5,k:"decentralisatie",t:"Decentralisatie",q:"Welke uitspraak over een zelfstandig bestuursorgaan (zbo) is juist?",o:["Een zbo is niet hiërarchisch ondergeschikt aan een minister","Een zbo is altijd een b-orgaan","Een zbo is geen bestuursorgaan in de zin van de Awb"],a:0,e:"Zbo is een andere indeling dan a- of b-orgaan. Een zbo kan a-orgaan of b-orgaan zijn; kenmerkend is dat het niet hiërarchisch onder een minister valt."},
{w:5,k:"vertrouwen",t:"Vertrouwensbeginsel",q:"Wat heeft de ABRvS in Amsterdams dakterras over het vertrouwensbeginsel geoordeeld?",o:["Gerechtvaardigde verwachtingen kunnen worden gehonoreerd als er geen zwaarder wegende belangen aan in de weg staan","Gerechtvaardigde verwachtingen kunnen alleen worden gehonoreerd bij een schriftelijke toezegging","Een toezegging van een onbevoegde ambtenaar kan nooit tot gerechtvaardigd vertrouwen leiden"],a:0,e:"Stap 3 van Dakterras: belangenafweging. Een mondelinge toezegging kan ook meetellen, en een toezegging van een ambtenaar kan onder omstandigheden aan het bevoegde orgaan worden toegerekend. Deze vraag stond zo op de eindtoets van 2025."},
{w:5,k:"vertrouwen",t:"Vertrouwensbeginsel",q:"Een baliemedewerker van de gemeente zegt tegen Ayla: ‘In het algemeen mag je een dakkapel aan de achterkant zonder vergunning bouwen.’ Ayla bouwt een dakkapel, maar haar situatie blijkt anders. Is er een toezegging in de zin van Dakterras?",o:["Waarschijnlijk niet: algemene informatie is meestal onvoldoende, het moet gaan om een bewust standpunt over haar concrete situatie","Ja, elke uitspraak van een gemeenteambtenaar is een toezegging","Ja, want een mondelinge uitspraak is altijd voldoende"],a:0,e:"Stap 1: kon de burger redelijkerwijs begrijpen dat het bestuur een bewust standpunt over haar concrete situatie innam? Algemene informatie is meestal te weinig."},
{w:5,k:"vertrouwen",t:"Vertrouwensbeginsel",q:"Een ambtenaar heeft na het bekijken van concrete bouwtekeningen schriftelijk toegezegd dat de gemeente niet zal handhaven. De buren lijden echter ernstige schade. Wat volgt uit Dakterras?",o:["Het bestuur moet belangen afwegen; zwaarder wegende belangen van derden kunnen honorering in de weg staan","Het bestuur moet de toezegging altijd nakomen","De toezegging telt niet, want de ambtenaar was niet zelf bevoegd"],a:0,e:"Stap 2 (toerekening) kan slagen ook als de ambtenaar niet zelf bevoegd was. In stap 3 worden belangen afgewogen. Kan het vertrouwen niet worden gehonoreerd, dan kan vergoeding van vertrouwensschade aan de orde zijn."},
{w:5,k:"evenredigheid",t:"Evenredigheid",q:"Volgens Harderwijk kan de evenredigheidstoets drie aspecten hebben. Welke?",o:["Geschiktheid, noodzakelijkheid en evenwichtigheid","Geschiktheid, noodzakelijkheid en redelijkheid","Legaliteit, legitiem doel en noodzakelijkheid"],a:0,e:"Harderwijk: geschiktheid, noodzakelijkheid, evenwichtigheid. Let op de term evenwichtigheid; ‘redelijkheid’ is fout (zo stond het in een afleider op de eindtoets). Optie 3 lijkt op het EVRM-schema."},
{w:5,k:"evenredigheid",t:"Evenredigheid",q:"Een burgemeester sluit een woning voor zes maanden na een drugsvondst. Het gezin met jonge kinderen moet eruit, hoewel de ouders van niets wisten. Bij welk aspect van de evenredigheidstoets weegt dit vooral mee?",o:["Evenwichtigheid","Geschiktheid","Noodzakelijkheid"],a:0,e:"Evenwichtigheid: zijn de gevolgen in deze concrete situatie niet onredelijk zwaar? Daar wegen de aanwezigheid van kinderen en de (geringe) verwijtbaarheid van de bewoners mee."},
{w:5,k:"evenredigheid",t:"Evenredigheid",q:"Een gemeente kan een overlastgevende hond laten aanlijnen of de hond in beslag nemen. Beide helpen even goed. Ze kiest inbeslagname. Welk aspect van evenredigheid is hier in het geding?",o:["Noodzakelijkheid","Geschiktheid","Evenwichtigheid"],a:0,e:"Noodzakelijkheid: kan hetzelfde doel worden bereikt met een minder belastende maatregel? Een maatregel kan geschikt zijn terwijl een minder ingrijpend alternatief ook werkt."},
{w:5,k:"evenredigheid",t:"Evenredigheid",st:true,q:"Lees de volgende stellingen.",s1:"Art. 3:4 lid 2 Awb bevat het evenredigheidsbeginsel.",s2:"Hoe ingrijpender de gevolgen van een besluit, hoe minder intensief de rechter toetst.",a:"JO",e:"Art. 3:4 lid 1 gaat over belangenafweging, lid 2 over evenredigheid. De intensiteit van de toetsing neemt juist toe naarmate de gevolgen ingrijpender en de belangen zwaarder zijn."},
{w:5,k:"awb",t:"Awb",q:"Een Awb-regel geldt alleen als een bijzondere wet haar van toepassing verklaart. Wat voor soort regel is dat?",o:["Facultatief recht","Aanvullend recht","Regelend recht"],a:0,e:"Facultatief: geldt pas als het van toepassing is verklaard. Aanvullend: geldt als de bijzondere regeling het onderwerp niet zelf regelt. Regelend: hoofdregel waarvan een wettelijk voorschrift afwijking kan toestaan."},
{w:5,k:"abbb",t:"Abbb",st:true,q:"Lees de volgende stellingen.",s1:"Als een formeel beginsel van behoorlijk bestuur is geschonden, moet het bestuursorgaan vaak een nieuw besluit nemen en daarbij de juiste spelregels volgen.",s2:"Het zorgvuldigheidsbeginsel, het motiveringsbeginsel en het rechtszekerheidsbeginsel hebben allemaal een formele en een materiële kant.",a:"JJ",e:"Bij een formeel gebrek (procedure) kan het orgaan het besluit opnieuw nemen, met mogelijk dezelfde uitkomst. Zorgvuldigheid, motivering en rechtszekerheid kennen elk een formele en een materiële variant. Zo stond het op de eindtoets van 2025."},
{w:5,k:"vertrouwen",t:"Abbb",q:"Welke uitspraak over het vertrouwensbeginsel is juist?",o:["Het is een ongeschreven beginsel, maar wel juridisch bindend","Het staat in art. 3:4 lid 2 Awb","Het is niet bindend omdat het niet is gecodificeerd"],a:0,e:"Het vertrouwensbeginsel is ongeschreven. Ook ongeschreven beginselen zijn juridisch bindend. Art. 3:4 lid 2 Awb bevat het evenredigheidsbeginsel."},

// ---------- WEEK 6 ----------
{w:6,k:"besluit",t:"Besluit",q:"Welke vier elementen bevat het besluitbegrip van art. 1:3 lid 1 Awb?",o:["Schriftelijke beslissing, bestuursorgaan, publiekrechtelijk, rechtshandeling","Schriftelijk, belanghebbende, algemene strekking, rechtsgevolg","Bestuursorgaan, bevoegdheid, motivering, bekendmaking"],a:0,e:"Een besluit is een schriftelijke beslissing van een bestuursorgaan, inhoudende een publiekrechtelijke rechtshandeling. Alle vier moeten aanwezig zijn."},
{w:6,k:"besluit",t:"Besluit",q:"Een handhaver zegt ter plekke mondeling tegen een kroegbaas dat zijn terras vanaf morgen dicht moet. Is dit een besluit in de zin van art. 1:3 lid 1 Awb?",o:["Nee, want het is niet schriftelijk; maar het kan wel op rechtsgevolg gericht zijn","Ja, want het is gericht op rechtsgevolg","Nee, want het is een feitelijke handeling"],a:0,e:"Een mondelinge beslissing is geen besluit, omdat het element ‘schriftelijk’ ontbreekt. Dat maakt het niet automatisch een feitelijke handeling."},
{w:6,k:"besluit",t:"Besluit",q:"De gemeente verkoopt een stuk grond aan een projectontwikkelaar. Wat voor handeling is dit?",o:["Een privaatrechtelijke rechtshandeling","Een publiekrechtelijke rechtshandeling","Een feitelijke handeling"],a:0,e:"De verkoop is gericht op rechtsgevolg, maar berust op het privaatrecht. Daarom is het geen besluit in de zin van de Awb."},
{w:6,k:"besluit",t:"Besluit",q:"Het college wijst een specifiek pand aan de Oudegracht aan als gemeentelijk monument. Welk criterium maakt dit tot een beschikking?",o:["Het zaakscriterium","Het persoonscriterium","Het criterium van algemene strekking"],a:0,e:"Zaakscriterium: gericht op een specifiek object waarvan de bijzondere eigenschappen doorslaggevend zijn. Persoonscriterium: gericht tot een bepaalde persoon of gesloten groep."},
{w:6,k:"besluit",t:"Besluit",q:"De gemeente wijst een aanvraag voor een parkeervergunning af. Is die afwijzing een beschikking?",o:["Ja, art. 1:3 lid 2 Awb rekent de afwijzing van een aanvraag uitdrukkelijk tot de beschikking","Nee, een afwijzing heeft geen rechtsgevolg","Nee, alleen een verleende vergunning is een beschikking"],a:0,e:"Art. 1:3 lid 2 Awb: een beschikking is een besluit dat niet van algemene strekking is, met inbegrip van de afwijzing van een aanvraag daarvan."},
{w:6,k:"besluit",t:"Besluit",q:"Het college stelt vast hoe het in het algemeen omgaat met zijn bevoegdheid om handhavingsverzoeken te behandelen. Wat is dit?",o:["Een beleidsregel","Een algemeen verbindend voorschrift","Een beschikking"],a:0,e:"Een beleidsregel gaat over de manier waarop een orgaan een bevoegdheid gebruikt. Er is geen rechtstreeks beroep tegen mogelijk (art. 8:3 Awb)."},
{w:6,k:"besluit",t:"Besluit",q:"Tegen welk besluit staat in beginsel rechtstreeks beroep bij de bestuursrechter open?",o:["Een besluit van algemene strekking dat geen AVV en geen beleidsregel is","Een algemeen verbindend voorschrift","Een beleidsregel"],a:0,e:"Art. 8:3 lid 1 sub a Awb sluit beroep tegen AVV's en beleidsregels uit. Tegen overige besluiten van algemene strekking staat in beginsel wel beroep open."},
{w:6,k:"besluit",t:"Besluit",q:"Een burger vraagt het college om handhavend op te treden tegen een illegale schuur van de buren. Het college besluit te gedogen. Wat is juist?",o:["De beslissing op het handhavingsverzoek kan appellabel zijn, ook al is een gedoogbeslissing in beginsel geen besluit","Een gedoogbeslissing is altijd een besluit","Tegen gedogen staat nooit enige rechtsbescherming open"],a:0,e:"Gedoogbeslissingen zijn in beginsel geen besluit. Een belanghebbende derde kan wel om handhaving verzoeken; de beslissing daarop kan appellabel zijn."},
{w:6,k:"besluit",t:"Besluit",q:"De gemeente laat in een brief weten hoe zij een bepaalde regel uitlegt, zonder iets voor de burger vast te stellen. Wat is dit meestal?",o:["Een bestuurlijk rechtsoordeel, meestal geen besluit","Een beschikking","Een algemeen verbindend voorschrift"],a:0,e:"Een bestuurlijk rechtsoordeel is uitleg van het bestuur. Er wordt geen rechtsgevolg beoogd, dus meestal is het geen besluit."},
{w:6,k:"besluit",t:"Beschikkingen",q:"Een subsidie wordt verleend, en het bestuursorgaan had daarbij ruimte om belangen af te wegen. Welke typering past?",o:["Begunstigend en discretionair","Belastend en gebonden","Begunstigend en gebonden"],a:0,e:"Een subsidie verbetert de rechtspositie (begunstigend). Ruimte om af te wegen betekent discretionair. Het zijn verschillende indelingen die samen kunnen gaan."},
{w:6,k:"beslissingsruimte",t:"Beslissingsruimte",q:"‘De burgemeester kan voor een gevaarlijke hond een aanlijngebod opleggen.’ Wat is ‘gevaarlijke hond’ in deze bepaling?",o:["De normconditie","De beleidsruimte","Het rechtsgevolg"],a:0,e:"De normconditie is de wettelijke voorwaarde voordat de bevoegdheid mag worden gebruikt. ‘Kan opleggen’ wijst op beleidsruimte."},
{w:6,k:"beslissingsruimte",t:"Beslissingsruimte",st:true,q:"Lees de volgende stellingen.",s1:"Een vage term in een wettelijke voorwaarde betekent automatisch dat het bestuur beoordelingsruimte heeft.",s2:"Ook als het bestuur beslissingsruimte heeft, kan de rechter het besluit toetsen aan de algemene beginselen van behoorlijk bestuur.",a:"OJ",e:"Je moet onderzoeken of de wetgever echt ruimte heeft willen geven; een vage term is niet automatisch beoordelingsruimte. Beslissingsruimte is geen vrije macht: de rechter toetst onder meer aan de abbb."},
{w:6,k:"beslissingsruimte",t:"Beslissingsruimte",q:"Bij welke bepaling heeft het bestuursorgaan de meeste beslissingsruimte?",o:["‘Onze Minister kan ontheffing verlenen van het verbod, indien hij dat in het belang van de veiligheid aanvaardbaar acht.’","‘Het verlof wordt geweigerd indien de aanvrager jonger is dan 18 jaar.’","‘Het is verboden een wapen voorhanden te hebben.’"],a:0,e:"‘Kan’ wijst op beleidsruimte en ‘aanvaardbaar acht’ op beoordelingsruimte. Bij een leeftijdsgrens is er geen ruimte (gebonden). Een verbod is een gedragsnorm voor burgers. Op de eindtoets moest je dit zelf in de Wet wapens en munitie opzoeken."},
{w:6,k:"beslissingsruimte",t:"Beslissingsruimte",q:"Het college gebruikt een bevoegdheid om horecavergunningen te weigeren in werkelijkheid om een concurrent van een gemeentelijk zwembad dwars te zitten. Welke norm wordt geschonden?",o:["Het verbod van détournement de pouvoir (art. 3:3 Awb)","Het motiveringsbeginsel (art. 3:47 Awb)","Het vertrouwensbeginsel"],a:0,e:"Art. 3:3 Awb: een bevoegdheid mag niet worden gebruikt voor een ander doel dan waarvoor zij is verleend."},
{w:6,k:"zorgvuldigheid",t:"Zorgvuldigheid",q:"Het college verklaart een hond gevaarlijk op basis van één onduidelijke melding, zonder verder onderzoek. Welk beginsel is vooral in het geding?",o:["Het zorgvuldigheidsbeginsel (art. 3:2 Awb)","Het kenbaarheidsvereiste (art. 3:47 Awb)","Het specialiteitsbeginsel"],a:0,e:"Art. 3:2 Awb: bij de voorbereiding de nodige kennis vergaren over de relevante feiten en belangen. Eén onduidelijke melding is geen deugdelijke feitelijke basis."},
{w:6,k:"zorgvuldigheid",t:"Motivering",q:"Een vergunning wordt geweigerd met alleen de zin: ‘Dit past niet binnen het beleid.’ Welk beginsel schiet vooral tekort?",o:["Het motiveringsbeginsel","Het zorgvuldigheidsbeginsel","Het vertrouwensbeginsel"],a:0,e:"Het bestuur legt niet uit welk beleid geldt, welke feiten relevant zijn en waarom die tot weigering leiden. Dat is een gebrek in de (deugdelijke en kenbare) motivering."},
{w:6,k:"zorgvuldigheid",t:"Motivering",q:"Wat is het verschil tussen art. 3:46 en art. 3:47 Awb?",o:["3:46 eist een deugdelijke motivering, 3:47 dat de motivering bij de bekendmaking wordt vermeld","3:46 gaat over horen, 3:47 over advies","3:46 eist een motivering bij beschikkingen, 3:47 bij AVV's"],a:0,e:"Deugdelijk (3:46): is de uitleg inhoudelijk draagkrachtig? Kenbaar (3:47): is de uitleg aan de belanghebbende meegedeeld?"},
{w:6,k:"zorgvuldigheid",t:"Motivering",q:"Het college wijkt af van een wettelijk voorgeschreven advies van een adviescommissie. Wat moet het doen?",o:["De redenen voor de afwijking in de motivering vermelden (art. 3:50 Awb)","Het advies alsnog volgen, want afwijken mag niet","Niets, want een advies is nooit bindend"],a:0,e:"Art. 3:50 Awb: wie afwijkt van een wettelijk voorgeschreven advies, moet dat in de motivering uitleggen."},
{w:6,k:"zorgvuldigheid",t:"Zorgvuldigheid",q:"Een aanvrager levert niet alle gegevens aan waarover hij redelijkerwijs kon beschikken. Welke plicht schendt hij?",o:["De informatieplicht van art. 4:2 lid 2 Awb","De onderzoeksplicht van art. 3:2 Awb","De motiveringsplicht van art. 3:46 Awb"],a:0,e:"De aanvrager moet de noodzakelijke gegevens verstrekken waarover hij redelijkerwijs kan beschikken. De onderzoeksplicht van het bestuur blijft daarnaast bestaan."},
{w:6,k:"zorgvuldigheid",t:"Toetsingsverbod",q:"Mag de rechter een besluit van het college toetsen aan de algemene beginselen van behoorlijk bestuur?",o:["Ja; het toetsingsverbod van art. 120 Gw gaat over formele wetten en verdragen, niet over bestuursbesluiten","Nee, art. 120 Gw verbiedt dat","Alleen als het besluit op een AMvB berust"],a:0,e:"Art. 120 Gw verbiedt toetsing van formele wetten en verdragen aan de Grondwet. Bestuursbesluiten kunnen wel aan de abbb worden getoetst."},

// ---------- WEEK 7 ----------
{w:7,k:"bezwaar",t:"Awb-structuur",q:"Wat staat (onder meer) geregeld in afdeling 7.2 van de Awb?",o:["Als het bezwaar ontvankelijk is, vindt op grondslag daarvan een heroverweging van het bestreden besluit plaats","Een belanghebbende kan tegen een besluit beroep instellen bij de bestuursrechter","Wie beroep bij de bestuursrechter kan instellen, moet eerst bezwaar maken"],a:0,e:"Afdeling 7.2 bevat bijzondere bepalingen over bezwaar, zoals de heroverweging van art. 7:11. De plicht om eerst bezwaar te maken staat in art. 7:1 (afdeling 7.1); beroep bij de rechter in hoofdstuk 8. Zo kwam het op de eindtoets van 2025."},
{w:7,k:"bezwaar",t:"Bezwaar",q:"Wat is géén functie van de verplichte voorprocedure (bezwaar)?",o:["Bevestigingsfunctie","Dossierfunctie","Zeeffunctie"],a:0,e:"De functies zijn: laagdrempelige rechtsbescherming, verlengde besluitvorming, zeeffunctie, dossierfunctie en signaleringsfunctie. Een ‘bevestigingsfunctie’ bestaat niet."},
{w:7,k:"bezwaar",t:"Bezwaar",q:"Welke functie van bezwaar staat centraal als geschillen al in de bezwaarfase worden opgelost, zodat ze niet bij de rechter komen?",o:["De zeeffunctie","De dossierfunctie","De signaleringsfunctie"],a:0,e:"Zeeffunctie: geschillen worden gefilterd voordat ze de rechter bereiken. Dossierfunctie: feiten en geschilpunten worden duidelijk. Signalering: fouten in beleid worden zichtbaar."},
{w:7,k:"bezwaar",t:"Bezwaar",q:"Wat toetst het bestuursorgaan in bezwaar?",o:["Rechtmatigheid én doelmatigheid, in beginsel ex nunc","Alleen rechtmatigheid, ex tunc","Alleen doelmatigheid, ex tunc"],a:0,e:"Art. 7:11 Awb: volledige heroverweging. In bezwaar beoordeelt het orgaan zowel rechtmatigheid als doelmatigheid, op basis van de situatie op het moment van de beslissing op bezwaar (ex nunc)."},
{w:7,k:"bezwaar",t:"Beroep",q:"Wat toetst de bestuursrechter in beroep?",o:["Alleen de rechtmatigheid, in beginsel ex tunc","Rechtmatigheid en doelmatigheid, ex nunc","Alleen de doelmatigheid, ex nunc"],a:0,e:"De rechter toetst rechtmatigheid naar de feiten en het recht op het moment van het bestreden besluit (ex tunc). Hij maakt zelf geen bestuurlijke keuzes."},
{w:7,k:"bezwaar",t:"Bezwaar",q:"Mag het bestuursorgaan het horen in bezwaar overslaan omdat het bezwaar ‘waarschijnlijk’ ongegrond is?",o:["Nee, alleen bij een kennelijk ongegrond bezwaar, waarover redelijkerwijs geen twijfel bestaat","Ja, het orgaan mag altijd zelf bepalen of het hoort","Ja, horen is in bezwaar niet verplicht"],a:0,e:"Art. 7:3 Awb: horen mag onder meer achterwege blijven bij een kennelijk niet-ontvankelijk of kennelijk ongegrond bezwaar. ‘Kennelijk’ betekent: geen twijfel mogelijk."},
{w:7,k:"bezwaar",t:"Bezwaar",q:"Sanne maakt bezwaar tegen een boete van €300. Het bestuursorgaan besluit de boete op uitsluitend haar bezwaar te verhogen naar €500. Welk verbod is in het geding?",o:["Het verbod van reformatio in peius","Het verbod van détournement de pouvoir","Het analogieverbod"],a:0,e:"Reformatio in peius: iemand mag door uitsluitend zijn eigen bezwaar in beginsel niet slechter af raken dan zonder dat bezwaar."},
{w:7,k:"termijnen",t:"Termijnen",q:"Een besluit is op maandag 2 maart bekendgemaakt. Wanneer begint de bezwaartermijn te lopen?",o:["Op dinsdag 3 maart, de dag na de bekendmaking","Op maandag 2 maart zelf","Op het moment dat de belanghebbende het besluit leest"],a:0,e:"Art. 6:8 Awb: de termijn van zes weken (art. 6:7) vangt aan met ingang van de dag na die waarop het besluit is bekendgemaakt."},
{w:7,k:"termijnen",t:"Termijnen",q:"Lars stuurt zijn bezwaarschrift per post. Hij post het op de laatste dag van de termijn; het komt vier dagen later aan. Is het bezwaar tijdig?",o:["Ja, het is vóór het einde van de termijn ter post bezorgd en binnen een week na afloop ontvangen","Nee, het moet binnen de termijn zijn ontvangen","Alleen als hij een verschoonbare reden heeft"],a:0,e:"Bij verzending per post is een bezwaarschrift tijdig als het vóór het einde van de termijn ter post is bezorgd en uiterlijk een week na afloop is ontvangen."},
{w:7,k:"termijnen",t:"Termijnen",q:"Fatima diende haar bezwaar twee weken te laat in, omdat zij in die periode met spoed in het ziekenhuis lag. Wat kan het bestuursorgaan (en later de rechter) oordelen?",o:["Dat de termijnoverschrijding verschoonbaar is (art. 6:11 Awb)","Dat het bezwaar prematuur is (art. 6:10 Awb)","Dat te laat altijd niet-ontvankelijk betekent"],a:0,e:"Bij een verschoonbare termijnoverschrijding kan de vertraging redelijkerwijs niet worden tegengeworpen, bijvoorbeeld door ernstige ziekte. Dat vraagt een individuele beoordeling."},
{w:7,k:"termijnen",t:"Termijnen",q:"Het bestuursorgaan beslist niet binnen de beslistermijn op een aanvraag. Wat kan de aanvrager doen?",o:["Een ingebrekestelling sturen en na twee weken beroep instellen wegens niet tijdig beslissen","Bezwaar maken tegen het uitblijven van een besluit","Direct naar de burgerlijke rechter stappen"],a:0,e:"Art. 6:12 Awb: na een schriftelijke ingebrekestelling en twee weken kan rechtstreeks beroep worden ingesteld. Het is dus in beginsel geen gewone bezwaarprocedure."},
{w:7,k:"termijnen",t:"Termijnen",q:"Wat is in beginsel de beslistermijn op een bezwaar als er geen adviescommissie is ingesteld?",o:["Zes weken","Twaalf weken","Acht weken"],a:0,e:"Art. 7:10 Awb: zes weken, of twaalf weken bij een adviescommissie, gerekend vanaf de dag na afloop van de bezwaartermijn. Verdaging met maximaal zes weken is mogelijk."},
{w:7,k:"rechtsgang",t:"Rechtsgang",q:"Welke rechter is de hogerberoepsrechter in een geschil over een bijstandsuitkering?",o:["De Centrale Raad van Beroep","De Afdeling bestuursrechtspraak van de Raad van State","Het College van Beroep voor het bedrijfsleven"],a:0,e:"Sociale zekerheid en bepaalde ambtenarenzaken: CRvB. Economisch bestuursrecht: CBb. Hoofdregel voor de rest: ABRvS."},
{w:7,k:"rechtsgang",t:"Rechtsgang",q:"Een inwoner van Utrecht wil beroep instellen tegen een besluit van het college van B&W van Amsterdam. Welke rechtbank is relatief bevoegd?",o:["De rechtbank Amsterdam, want bij een decentraal bestuursorgaan telt de vestigingsplaats van dat orgaan","De rechtbank Midden-Nederland, want de woonplaats van de indiener is bepalend","Iedere rechtbank naar keuze van de indiener"],a:0,e:"Art. 8:7 Awb: bij een decentraal bestuursorgaan is de vestigingsplaats van het orgaan bepalend. Bij andere bestuursorganen telt de woonplaats van de indiener."},
{w:7,k:"rechtsgang",t:"Rechtsgang",q:"Welke stelling over de rechtsmachtverdeling tussen bestuursrechter en burgerlijke rechter is juist?",o:["De eiser is bij de burgerlijke rechter niet-ontvankelijk als er nog een bestuursrechtelijke rechtsgang openstaat","De burgerlijke rechter staat pas open als alle bestuursrechtelijke rechtsmiddelen zijn uitgeput","Voor toegang tot de burgerlijke rechter is een besluit in de zin van de Awb vereist"],a:0,e:"De burgerlijke rechter is restrechter. Staat er een bestuursrechtelijke rechtsgang open, dan moet je daar naartoe. Zo stond deze vraag op de eindtoets van 2025."},
{w:7,k:"rechtsgang",t:"Rechtsbescherming",q:"Welke stelling over het relatief informele karakter van de bestuursrechtspraak is onjuist?",o:["De bestuursrechtspraak regelt voor iedereen een goede advocaat om tot ongelijkheidscompensatie te komen","De bestuursrechtspraak is laagdrempelig door het relatief lage griffierecht","Door een actieve rol van de bestuursrechter neemt de kans op procedurele rechtvaardigheid toe"],a:0,e:"Een advocaat is in het bestuursrecht niet verplicht, maar de bestuursrechtspraak regelt er ook niet voor iedereen een. Ongelijkheid wordt gecompenseerd door laagdrempeligheid en een actieve rechter."},
{w:7,k:"bezwaar",t:"Beroep",q:"De rechter oordeelt dat het beroep slaagt omdat het besluit onvoldoende is gemotiveerd. Welke uitspraak doet hij?",o:["Het beroep is gegrond","Het beroep is niet-ontvankelijk","Het beroep is ongegrond"],a:0,e:"Art. 8:70 Awb: gegrond als het beroep geheel of gedeeltelijk slaagt. Niet-ontvankelijk gaat over procedurele voorwaarden; ongegrond betekent dat de gronden niet slagen."},
{w:7,k:"bezwaar",t:"Beroep",q:"De rechter vernietigt een besluit, maar laat de rechtsgevolgen ervan in stand omdat het orgaan hetzelfde besluit opnieuw met een goede motivering zou nemen. Op welk artikel is dit gebaseerd?",o:["Art. 8:72 Awb","Art. 8:70 Awb","Art. 6:16 Awb"],a:0,e:"Art. 8:72 Awb geeft de rechter bij een gegrond beroep mogelijkheden zoals vernietigen, zelf voorzien en rechtsgevolgen in stand laten. Art. 8:70 noemt de soorten uitspraak."},
{w:7,k:"bezwaar",t:"Voorlopige voorziening",q:"De gemeente wil een monumentale boom volgende week kappen. Een omwonende heeft bezwaar gemaakt. Wat kan hij doen om de kap tegen te houden?",o:["Een voorlopige voorziening vragen (art. 8:81 Awb), omdat bezwaar het besluit niet schorst","Niets, want het bezwaar schorst het besluit al automatisch","Direct hoger beroep instellen bij de ABRvS"],a:0,e:"Bezwaar en beroep schorsen niet (art. 6:16 Awb). Bij spoedeisend belang en een lopende procedure (connexiteit) kan een voorlopige voorziening worden gevraagd."},
{w:7,k:"bezwaar",t:"Bezwaar overslaan",q:"In welk geval hoeft een belanghebbende géén bezwaar te maken voordat hij beroep instelt?",o:["Als het besluit is voorbereid met de uniforme openbare voorbereidingsprocedure (afdeling 3.4 Awb)","Als hij het besluit erg onrechtvaardig vindt","Als hij een advocaat heeft"],a:0,e:"Bezwaar kan worden overgeslagen bij de uniforme openbare voorbereidingsprocedure, bij een beslissing op bezwaar, bij niet tijdig beslissen, als een bijzondere wet dat bepaalt of met instemming voor rechtstreeks beroep (art. 7:1a)."},
{w:7,k:"rechtsgang",t:"Bestuursrechtspraak",q:"Wat is het verschil tussen recours subjectif en recours objectif?",o:["Subjectif: de individuele burger beschermen; objectif: bewaken dat het bestuur zich aan het recht houdt","Subjectif: beroep bij de rechtbank; objectif: hoger beroep","Subjectif: bezwaar; objectif: beroep"],a:0,e:"De twee doelen van bestuursrechtelijke rechtsbescherming: individuele rechtsbescherming en rechtmatigheidscontrole van het bestuur."},

// ---------- WEEK 8 ----------
{w:8,k:"grondrechten",t:"Soorten grondrechten",q:"De vrijheid van vergadering en betoging is vooral een:",o:["Klassiek grondrecht, gericht op onthouding van overheidsinmenging","Sociaal grondrecht, gericht op actieve zorg van de overheid","Politiek participatierecht zonder enige vrijheidskant"],a:0,e:"Klassieke grondrechten beschermen tegen overheidsinmenging en sluiten aan bij negatieve vrijheid. Ook hier kan wel een positieve verplichting bestaan, bijvoorbeeld een vreedzame demonstratie beschermen."},
{w:8,k:"grondrechten",t:"Soorten grondrechten",st:true,q:"Lees de volgende stellingen.",s1:"Klassieke grondrechten kunnen ook positieve verplichtingen voor de overheid meebrengen.",s2:"Sociale grondrechten zijn juridisch betekenisloos.",a:"JO",e:"Het onderscheid is niet absoluut: ook klassieke rechten kunnen de overheid tot actie verplichten. Sociale grondrechten verplichten tot zorg en inspanning, al geven ze meestal geen recht op een concreet resultaat."},
{w:8,k:"reikwijdte",t:"Reikwijdte",q:"Een kerkgenootschap beroept zich op de godsdienstvrijheid. Om welke vraag gaat het eerst?",o:["De personele reikwijdte: kan deze rechtspersoon zich op het grondrecht beroepen?","De materiële reikwijdte: valt de activiteit onder het grondrecht?","De beperking: grijpt de overheid in?"],a:0,e:"Personele reikwijdte: wie wordt beschermd? Ook rechtspersonen kunnen bepaalde grondrechten hebben, zoals een kerkgenootschap bij godsdienstvrijheid."},
{w:8,k:"reikwijdte",t:"Reikwijdte",q:"Welke uitspraak over beperking en schending is juist?",o:["Een beperking is pas een schending als zij niet aan de voorwaarden voldoet","Iedere beperking van een grondrecht is een schending","Een schending is een beperking die wel aan de voorwaarden voldoet"],a:0,e:"Een toegestane beperking voldoet aan alle toepasselijke voorwaarden. Een schending doet dat niet."},
{w:8,k:"reikwijdte",t:"Reikwijdte",q:"Welk grondrecht is absoluut en kan ook in een noodtoestand niet worden beperkt?",o:["Het folterverbod (art. 3 EVRM)","De vrijheid van meningsuiting (art. 10 EVRM)","De vrijheid van vergadering (art. 11 EVRM)"],a:0,e:"Het folterverbod is absoluut. Uitingsvrijheid en vergadervrijheid zijn relatief: beperking is mogelijk onder voorwaarden."},
{w:8,k:"gwbeperking",t:"Grondwet",q:"Wat betekent ‘wet’ in een grondwettelijke beperkingsclausule?",o:["Een wet in formele zin","Iedere regel van nationaal recht, ook ongeschreven recht","Iedere wet in materiële zin"],a:0,e:"In de Grondwet betekent ‘wet’ een wet in formele zin. In het EVRM is ‘wet’ veel ruimer: ook lagere regelgeving en ongeschreven recht."},
{w:8,k:"gwbeperking",t:"Grondwet",q:"Een burgemeester verbiedt een demonstratie omdat de boodschap ‘schadelijk voor het imago van de stad’ is. Waarom is dat volgens art. 9 lid 2 Gw problematisch?",o:["Het is geen toegestaan doel: alleen gezondheid, verkeer en het bestrijden of voorkomen van wanordelijkheden","De burgemeester mag nooit een demonstratie beperken","Art. 9 Gw beschermt alleen demonstraties binnen gebouwen"],a:0,e:"Art. 9 lid 2 Gw noemt de doelen waarvoor beperking mag. Een ander doel volstaat niet, ook als het bestuur dat belangrijk vindt. Onenigheid met de boodschap is nooit genoeg."},
{w:8,k:"gwbeperking",t:"Grondwet",st:true,q:"Lees de volgende stellingen.",s1:"Als de Grondwet delegatie van de beperkingsbevoegdheid toestaat, mag een burgemeester het grondrecht automatisch beperken.",s2:"Bij ‘behoudens ieders verantwoordelijkheid volgens de wet’ mag de beperkingsbevoegdheid niet worden gedelegeerd.",a:"OJ",e:"Delegatie mogen toestaan is iets anders dan daadwerkelijk gedelegeerd hebben: er moet ook een concrete wettelijke grondslag voor het lagere orgaan bestaan. ‘Behoudens ieders verantwoordelijkheid volgens de wet’ betekent: geen delegatie."},
{w:8,k:"gwbeperking",t:"Grondwet",q:"Welk grondrecht kent procedurecriteria zoals voorafgaande legitimatie en schriftelijke verslaglegging?",o:["Het recht op onaantastbaarheid van de woning (art. 12 Gw)","De vrijheid van godsdienst (art. 6 Gw)","De vrijheid van vergadering en betoging (art. 9 Gw)"],a:0,e:"Art. 12 Gw: binnentreden in een woning vereist onder meer voorafgaande legitimatie, mededeling van het doel en schriftelijke verslaglegging."},
{w:8,k:"evrm",t:"EVRM",q:"Welke drie voorwaarden gelden voor een beperking van art. 8 tot en met 11 EVRM?",o:["Bij wet voorzien, legitiem doel, noodzakelijk in een democratische samenleving","Geschiktheid, noodzakelijkheid, evenwichtigheid","Competentie, doel, procedure"],a:0,e:"Het EVRM-schema staat in het tweede lid van die artikelen. Optie 2 is de evenredigheidstoets uit Harderwijk; optie 3 zijn de Grondwet-criteria."},
{w:8,k:"evrm",t:"EVRM",q:"Een beperking berust op een geheime instructie van de politie die burgers niet kunnen inzien. Aan welke EVRM-eis voldoet dit waarschijnlijk niet?",o:["Bij wet voorzien: de rechtsbasis moet toegankelijk en voorzienbaar zijn","Legitiem doel","Noodzakelijk in een democratische samenleving"],a:0,e:"‘Bij wet voorzien’ is ruim (ook lagere regels), maar de basis moet toegankelijk (accessible) en voorzienbaar (foreseeable) zijn en bescherming bieden tegen willekeur."},
{w:8,k:"evrm",t:"EVRM",q:"Een burgemeester verbiedt een hele demonstratie, terwijl een paar voorschriften (een andere route, een maximaal aantal deelnemers) het risico op wanordelijkheden ook hadden beperkt. Welk aspect van ‘noodzakelijk in een democratische samenleving’ is vooral in het geding?",o:["Subsidiariteit","Geschiktheid","Legitiem doel"],a:0,e:"Subsidiariteit: kan het doel met een minder beperkende maatregel worden bereikt? Een volledig verbod is het zwaarste middel."},
{w:8,k:"evrm",t:"EVRM",q:"Wat is de margin of appreciation?",o:["De beoordelingsruimte die het EHRM aan nationale autoriteiten laat","De termijn waarbinnen een klacht bij het EHRM moet worden ingediend","De ruimte van de wetgever om af te wijken van de Grondwet"],a:0,e:"De appreciatiemarge verschilt per recht, activiteit, doel en ernst van de beperking. Het EHRM blijft wel controleren."},
{w:8,k:"evrm",t:"Grondwet en EVRM",st:true,q:"Lees de volgende stellingen.",s1:"Een maatregel die aan de Grondwet voldoet, kan toch het EVRM schenden.",s2:"Art. 120 Gw verbiedt de rechter om formele wetten te toetsen aan rechtstreeks werkende bepalingen van het EVRM.",a:"JO",e:"Je moet beide systemen afzonderlijk onderzoeken. Art. 120 Gw verbiedt toetsing aan de Grondwet; toetsing aan eenieder verbindende verdragsbepalingen zoals het EVRM mag wel."},
{w:8,k:"grondrechten",t:"Grondrechten",q:"Wanneer is het EU-Grondrechtenhandvest van toepassing op een lidstaat?",o:["Wanneer de lidstaat handelt binnen het toepassingsgebied van het EU-recht","Altijd, bij iedere nationale situatie","Alleen als het EVRM niet van toepassing is"],a:0,e:"Het Handvest geldt voor lidstaten wanneer zij binnen het toepassingsgebied van het EU-recht handelen, niet automatisch bij iedere nationale situatie."},
{w:8,k:"casus",t:"Demonstraties",q:"Demonstranten bij een abortuskliniek worden naar een plek verderop verplaatst. Waar let de rechter onder het EVRM vooral op?",o:["Of de demonstranten hun boodschap nog effectief kunnen overbrengen (zicht- en geluidsafstand)","Of de burgemeester het eens is met de boodschap","Of de demonstranten de kliniek kunnen betreden"],a:0,e:"Bij de evenredigheid speelt ‘sight and sound’: kunnen de demonstranten hun publiek nog zien en horen? Een bufferzone is niet altijd verboden en een verplaatsing niet altijd toegestaan; de omstandigheden beslissen."},

// ---------- EXTRA (eindtoets) ----------
{w:9,k:"parlstelsel",t:"Ministerraad",q:"Welke stelling over de ministeriële verantwoordelijkheid is juist?",o:["Ministers zijn verantwoordelijk voor besluiten die in de ministerraad zijn genomen, ook als ze daar zelf niet mee instemden","Ministers zijn nooit verantwoordelijk voor het handelen van de Koning","Ministers zijn verantwoordelijk voor het doen en laten van de leden van hun fractie"],a:0,e:"Eenheid van regeringsbeleid (art. 45 lid 3 Gw): de ministerraad besluit over het algemeen beleid en ministers dragen dat uit. Ministers zijn juist wél verantwoordelijk voor de Koning (art. 42 lid 2 Gw). Deze vraag stond zo op de eindtoets van 2025."},
{w:9,k:"parlstelsel",t:"Ministerraad",q:"Een minister doet tijdens een Kamerdebat toezeggingen namens het kabinet, terwijl hij nog niet weet of zijn collega's daarmee instemmen. Waarom is dat ongebruikelijk?",o:["Een minister spreekt namens het gehele kabinet; het is vreemd eerst toe te zeggen en pas daarna steun te zoeken","Een minister mag in een debat nooit iets toezeggen","De oppositie hoort bewindspersonen te steunen"],a:0,e:"Door de eenheid van kabinetsbeleid spreekt een bewindspersoon namens het hele kabinet. Toezeggingen moeten dus door het kabinet gedragen worden."},
{w:9,k:"bevoegdheden",t:"Bevoegdheden",q:"Een minister besluit een aantal voordrachten voor een koninklijke onderscheiding niet te ondertekenen. Om wat voor bevoegdheid gaat het?",o:["Een bestuursbevoegdheid","Een regelgevende bevoegdheid","Een wetgevende bevoegdheid"],a:0,e:"Het gaat om beslissingen in concrete, individuele gevallen; geen algemene regels. Let op: op de eindtoets stond ook ‘beleidsbevoegdheid’ als afleider; dat is geen aparte categorie naast regelgevende en bestuursbevoegdheid."},
{w:9,k:"organen",t:"Grondwet",st:true,q:"Lees de volgende stellingen.",s1:"De Grondwet bepaalt dat de Staten-Generaal bestaan uit de Eerste Kamer en de Tweede Kamer.",s2:"De Grondwet gelast nieuwe verkiezingen na de ontbinding van een van de Kamers.",a:"JJ",e:"Art. 51 Gw: de Staten-Generaal bestaan uit de Tweede en de Eerste Kamer. Art. 64 Gw: het besluit tot ontbinding verplicht tot nieuwe verkiezingen voor de ontbonden Kamer."},
{w:9,k:"regelgeving",t:"Regelgeving",q:"In je wettenbundel staat een regeling met als aanhef: ‘Op de voordracht van Onze Minister van Justitie en Veiligheid; De Afdeling advisering van de Raad van State gehoord; Hebben goedgevonden en verstaan.’ De Staten-Generaal worden niet genoemd. Wat voor regeling is dit?",o:["Een algemene maatregel van bestuur","Een wet in formele zin","Een ministeriële regeling"],a:0,e:"Een AMvB wordt op voordracht van een minister, na advies van de Raad van State, door de regering vastgesteld. Bij een formele wet staat ‘met gemeen overleg der Staten-Generaal’. Een ministeriële regeling begint met ‘De Minister van ... Besluit:’. Staat de aanhef niet in je bundel, kijk dan naar het opschrift (‘Wet van ...’, ‘Besluit van ...’, ‘Regeling van de Minister ...’) en de vindplaats (Stb. of Stcrt.)."},
{w:9,k:"trias",t:"Trias politica",q:"Welke stelling over de trias politica in het Nederlandse constitutionele bestel is juist?",o:["Als alle overheidsmacht in één orgaan is verenigd, is dat in strijd met de scheiding der machten","De trias stelt dat de ambten van wetgevende, uitvoerende en rechterlijke macht in Nederland strikt gescheiden zijn","De trias stelt dat samenwerking tussen rechterlijke en uitvoerende macht mag, zolang de wetgevende macht onafhankelijk blijft"],a:0,e:"De kern van machtenscheiding is het voorkomen van machtsconcentratie. Nederland kent geen strikte scheiding: machten werken samen en controleren elkaar. Deze vraag stond zo op de eindtoets van 2025."},
{w:9,k:"evenredigheid",t:"Evenredigheid",q:"De burgemeester sluit een woning na een drugsvondst in het appartement van de volwassen zoon. De ouders, eigenaren van de woning, wisten van niets en gaan in beroep. Wat is juist?",o:["Bij de evenredigheidstoets kan meewegen dat de ouders als eigenaar verantwoordelijk zijn voor wat er in de woning gebeurt","De arrestatie van de zoon is niet relevant voor de afweging","De evenredigheidstoets kent drie stappen: geschiktheid, noodzakelijkheid en redelijkheid"],a:0,e:"Bij de evenwichtigheid weegt de verwijtbaarheid en verantwoordelijkheid van de eigenaar mee. De aanleiding is wel relevant. En de derde stap heet evenwichtigheid, niet redelijkheid. Vrijwel deze casus stond op de eindtoets van 2025."}
];
